public class Base64Alphabet {

    public static char charFor(int index) {
        if (index >= 0 && index <= 25) {
            return (char) ('A' + index);
        } else if (index >= 26 && index <= 51) {
            return (char) ('a' + index - 26);
        } else if (index >= 52 && index <= 61) {
            return (char) ('0' + index - 52);
        } else if (index == 62) {
            return '+';
        } else if (index == 63) {
            return '/';
        } else {
            return '?';
        }
    }

    public static String encode(int[] bytes) {
        if (bytes == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i += 3) {
            int remaining = bytes.length - i;
            int b0 = bytes[i];
            int b1 = remaining > 1 ? bytes[i + 1] : 0;
            int b2 = remaining > 2 ? bytes[i + 2] : 0;
            int block = (b0 << 16) | (b1 << 8) | b2;

            sb.append(charFor((block >> 18) & 63));
            sb.append(charFor((block >> 12) & 63));
            if (remaining > 1) {
                sb.append(charFor((block >> 6) & 63));
            } else {
                sb.append('=');
            }
            if (remaining > 2) {
                sb.append(charFor(block & 63));
            } else {
                sb.append('=');
            }
        }
        return sb.toString();
    }
}
